H.background();
const Vs = P.Vs, R = Math.max(0.1, P.R), C = Math.max(0.01, P.C);
const tau = R * C;
const win = Math.max(0.5, 6 * tau);
const phase = (t % (2 * win)) / win;
const charging = phase < 1;
const tt = (charging ? phase : phase - 1) * win;
const Vc = charging ? Vs * (1 - Math.exp(-tt / tau)) : Vs * Math.exp(-tt / tau);
const v = H.plot2d({ xMin: 0, xMax: win, yMin: 0, yMax: Vs * 1.1 + 0.01, pad: 52 });
v.grid(); v.axes();
if (charging) {
  v.fn(x => Vs * (1 - Math.exp(-x / tau)), { color: H.colors.accent, width: 3 });
} else {
  v.fn(x => Vs * Math.exp(-x / tau), { color: H.colors.accent2, width: 3 });
}
v.line(tau, 0, tau, Vs * 1.1, { color: H.colors.violet, width: 1.5, dash: [5, 5] });
v.text("τ", tau, Vs * 1.05, { color: H.colors.violet, size: 13 });
v.dot(tt, Vc, { r: 6, fill: H.colors.warn });
v.line(tt, 0, tt, Vc, { color: H.colors.good, width: 1.5, dash: [4, 4] });
H.text("RC circuit: Vc(t) = Vs(1 − e^(−t/τ)),  τ = R·C", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text((charging ? "CHARGING" : "DISCHARGING") + "   τ = " + tau.toFixed(2) + " s   t = " + tt.toFixed(2) + " s   Vc = " + Vc.toFixed(2) + " V", 24, 54, { color: H.colors.sub, size: 13 });
H.legend([{ label: "charge", color: H.colors.accent }, { label: "discharge", color: H.colors.accent2 }], H.W - 150, 28);
